create table if not exists public.provider_system_reconciliations (id uuid primary key default gen_random_uuid(), organization_id uuid not null, provider_relationship_id uuid not null, legal_entity_id uuid not null, system_code text not null, mapping_type text not null, reconciliation_status text not null, expected_fingerprint text, actual_fingerprint text, checked_at timestamptz not null default now(), created_at timestamptz not null default now());
